/**
 * The environment's gameplay data (content/environment.ts, generated by tools/content/environment.mjs): the schema,
 * every species' surface, nav and concealment, and the pinned resolution. fixtures/environment-resolved.json pins
 * every species' sizes and shapes by assetVersion: a generator or content change that moves a collider fails here
 * unless the species' assetVersion is bumped (with a note in its content file) and the fixture entry added for the
 * new version, on purpose (a cover change is a gameplay change; the owner reviews it).
 */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { EnvironmentSpeciesSchema } from '../src/content/environmentSchema.ts';
import { ENV_SPECIES, MAP_BUDGETS, envTilts, SURFACE_TYPES, envModelFile, envPropDefinition, envVariant, getEnvSpecies, getProp, loadMap, newMapDocument, propMaterial, propSurface, validateMap, type EnvShape, type MapDocument } from '../src/index.ts';

const fixture = JSON.parse(readFileSync(new URL('./fixtures/environment-resolved.json', import.meta.url), 'utf8')) as Record<string, unknown>;

/** What the fixture pins for a species at its assetVersion. */
const resolved = (id: string) => {
  const s = getEnvSpecies(id)!;
  return { surface: s.surface, nav: s.nav, role: s.role, conceals: s.conceals, variants: s.variants.map((v) => ({ index: v.index, name: v.name, size: v.size, shapes: v.shapes })) };
};

/** A shape's points (capsules: both ends widened by the radius on every axis). */
function shapePoints(sh: EnvShape): [number, number, number][] {
  if (sh.kind === 'capsule') return [sh.a, sh.b].flatMap((p) => [-1, 1].flatMap((d) => [[p[0] + d * sh.r, p[1], p[2]], [p[0], p[1], p[2] + d * sh.r], [p[0], p[1] + d * sh.r, p[2]]] as [number, number, number][]));
  if (sh.kind === 'hull') return sh.points.map((p) => [...p] as [number, number, number]);
  if (sh.kind === 'box') return [[...sh.min], [...sh.max]] as [number, number, number][];
  const out: [number, number, number][] = [];
  for (let i = 0; i < sh.positions.length; i += 3) out.push([sh.positions[i]!, sh.positions[i + 1]!, sh.positions[i + 2]!]);
  return out;
}

describe('environment data', () => {
  it('every species matches the schema', () => {
    expect(ENV_SPECIES.length).toBe(23);
    for (const s of ENV_SPECIES) expect(() => EnvironmentSpeciesSchema.parse(s), s.id).not.toThrow();
  });

  it('the Phase 1 species, the plants brush flowers, fern, pebbles and eelgrass and the Phase 2 trees, bushes and hedges, each with material variants', () => {
    expect(ENV_SPECIES.map((s) => s.id).sort()).toEqual([
      'env.broadleaf.acacia', 'env.broadleaf.maple', 'env.broadleaf.oak', 'env.cactus.saguaro', 'env.cliff.face', 'env.conifer.pine_tall', 'env.conifer.spruce', 'env.deadwood.log', 'env.fern.bracken', 'env.flower.meadow', 'env.grass.clump',
      'env.hedge.privet', 'env.hedge.yew', 'env.palm.coconut', 'env.palm.leaning', 'env.rock.boulder_angular', 'env.rock.boulder_round', 'env.rock.outcrop', 'env.rock.pebbles', 'env.rock.slab', 'env.shrub.broadleaf', 'env.shrub.laurel', 'env.water.eelgrass',
    ]);
    for (const s of ENV_SPECIES) {
      expect(s.variants.length, s.id).toBeGreaterThanOrEqual(2);
      // Material variants share the structure, so they share the collision exactly.
      for (const v of s.variants.slice(1)) {
        expect(v.shapes, s.id).toEqual(s.variants[0]!.shapes);
        expect(v.size, s.id).toEqual(s.variants[0]!.size);
      }
    }
    // Ground cover (grass, flowers, eelgrass) and pebbles are decoration only: no collision, no nav, no concealment.
    // The fern is ground cover that conceals (it replaces the Kenney fern): cover, still no collision or nav.
    for (const s of ENV_SPECIES.filter((x) => x.category === 'groundcover' || x.category === 'rock')) expect([s.role, s.nav, s.conceals !== null, s.variants[0]!.shapes.length], s.id).toEqual([s.id === 'env.fern.bracken' ? 'cover' : 'decorative', 'none', s.id === 'env.fern.bracken', 0]);
    expect(getEnvSpecies('env.rock.pebbles')!.surface).toBe('rock');
  });

  it('every species has a surface the server and client know, nav and concealment data', () => {
    for (const s of ENV_SPECIES) {
      expect(SURFACE_TYPES[s.surface], s.id).toBeDefined();
      for (const v of s.variants) for (const sh of v.shapes) expect(SURFACE_TYPES[sh.surface], s.id).toBeDefined();
      expect(['none', 'obstacle', 'boundary']).toContain(s.nav);
      expect(s.conceals === null || (s.conceals.radius > 0 && s.conceals.height > 0), s.id).toBe(true);
    }
    // Trees are bark (heavy wood: full cover), rocks stone, plants foliage.
    expect(propMaterial('env.broadleaf.oak')).toBe('heavy_wood');
    expect(propMaterial('env.conifer.pine_tall')).toBe('heavy_wood');
    expect(propMaterial('env.rock.boulder_angular')).toBe('stone');
    expect(propMaterial('env.cliff.face')).toBe('stone');
    expect(propSurface('env.shrub.broadleaf')).toBe('foliage');
    // The shrub and the fern conceal (the rule bushes follow); grass is decoration only.
    expect(ENV_SPECIES.filter((s) => s.conceals).map((s) => s.id).sort()).toEqual(['env.fern.bracken', 'env.shrub.broadleaf', 'env.shrub.laurel']);
    // Phase 2: palms and the saguaro are full cover like trunks; the hedges are walls of bark-hard cover (the Kenney
    // hedges they replace stopped rounds), the laurel bush foliage.
    for (const id of ['env.broadleaf.maple', 'env.broadleaf.acacia', 'env.conifer.spruce', 'env.palm.coconut', 'env.palm.leaning', 'env.cactus.saguaro', 'env.hedge.privet', 'env.hedge.yew']) expect(propMaterial(id), id).toBe('heavy_wood');
    expect(propSurface('env.shrub.laurel')).toBe('foliage');
    const grass = getEnvSpecies('env.grass.clump')!;
    expect([grass.role, grass.nav, grass.variants[0]!.shapes.length]).toEqual(['decorative', 'none', 0]);
  });

  it('collision: trunks stop everything, limbs only shots; boulders a hull; cliffs a mesh under 200 triangles; plants none', () => {
    const oak = envVariant(getEnvSpecies('env.broadleaf.oak')!, 0).shapes;
    expect(oak.filter((s) => s.blocks === 'all').every((s) => s.kind === 'capsule' && s.r >= 0.25)).toBe(true);
    expect(oak.filter((s) => s.blocks === 'shots').length).toBeGreaterThan(0);
    const pine = envVariant(getEnvSpecies('env.conifer.pine_tall')!, 0).shapes;
    expect(pine.every((s) => s.kind === 'capsule' && s.blocks === 'all')).toBe(true);
    const boulder = envVariant(getEnvSpecies('env.rock.boulder_angular')!, 0).shapes;
    expect(boulder.length === 1 && boulder[0]!.kind === 'hull' && boulder[0]!.points.length <= 32).toBe(true);
    const cliff = envVariant(getEnvSpecies('env.cliff.face')!, 0).shapes;
    expect(cliff.length === 1 && cliff[0]!.kind === 'mesh' && cliff[0]!.indices.length / 3 <= 200).toBe(true);
    expect(envVariant(getEnvSpecies('env.shrub.broadleaf')!, 0).shapes).toEqual([]);
    // Phase 2: palm trunks and the saguaro's column and arms are capsules that stop everything; a hedge is one hull
    // that stops everything (a wall, nav obstacle) and is drawn upright (it doesn't lean with the ground); the laurel
    // bush has no collision.
    for (const id of ['env.palm.coconut', 'env.palm.leaning', 'env.cactus.saguaro', 'env.conifer.spruce']) {
      const shapes = envVariant(getEnvSpecies(id)!, 0).shapes;
      expect(shapes.length > 0 && shapes.every((s) => s.kind === 'capsule' && s.blocks === 'all' && s.r >= 0.12), id).toBe(true);
    }
    expect(envVariant(getEnvSpecies('env.cactus.saguaro')!, 0).shapes.length).toBeGreaterThanOrEqual(5);
    for (const id of ['env.hedge.privet', 'env.hedge.yew']) {
      const s = getEnvSpecies(id)!;
      const shapes = envVariant(s, 0).shapes;
      expect([shapes.length, shapes[0]!.kind, shapes[0]!.blocks, s.nav, s.role, envTilts(id)], id).toEqual([1, 'hull', 'all', 'obstacle', 'blocking', false]);
    }
    // Lying along z as the Kenney hedges do (Replace all keeps their facing): privet 4.8 m long and 1.2 m high, yew 3.6 m and 2.2 m.
    expect(getEnvSpecies('env.hedge.privet')!.variants[0]!.size[2]).toBeCloseTo(4.8, 0);
    expect(getEnvSpecies('env.hedge.yew')!.variants[0]!.size[1]).toBeCloseTo(2.2, 0);
    expect(envVariant(getEnvSpecies('env.shrub.laurel')!, 0).shapes).toEqual([]);
    expect(envTilts('env.shrub.laurel')).toBe(true);
    // The rocks Rockfall Canyon needs, near the size of the Kenney pieces they stand in for (prop.rock_large,
    // rock_flat, rocks_tall): the round boulder and the slab one hull each, the outcrop one hull per mass (its notches
    // stay open), all stone, all solid nav obstacles. The slab's top is flat enough to walk on (a 0.1 m fall at most).
    for (const [id, hulls, role, like] of [['env.rock.boulder_round', 1, 'cover', 'prop.rock_large'], ['env.rock.slab', 1, 'cover', 'prop.rock_flat'], ['env.rock.outcrop', 3, 'blocking', 'prop.rocks_tall']] as const) {
      const s = getEnvSpecies(id)!;
      const shapes = envVariant(s, 0).shapes;
      expect([shapes.length, s.nav, s.role, s.surface, propMaterial(id)], id).toEqual([hulls, 'obstacle', role, 'rock', 'stone']);
      expect(shapes.every((sh) => sh.kind === 'hull' && sh.blocks === 'all' && sh.points.length <= 32), id).toBe(true);
      const want = getProp(like)!.size;
      s.variants[0]!.size.forEach((v, k) => expect(Math.abs(v - want[k]!), `${id} axis ${k}`).toBeLessThan(0.3));
    }
    const slabTop = (envVariant(getEnvSpecies('env.rock.slab')!, 0).shapes[0] as Extract<EnvShape, { kind: 'hull' }>).points.map((p) => p[1]).filter((y) => y > 0.28);
    expect(slabTop.length).toBeGreaterThanOrEqual(5);
    expect(Math.max(...slabTop)).toBeCloseTo(0.4, 2);
    expect(Math.max(...slabTop) - Math.min(...slabTop)).toBeLessThanOrEqual(0.1);
    // The fallen log: one hull along z the size of the Kenney log's box (the stubs do not collide), bark (heavy
    // wood, as prop.log is), a solid nav obstacle. Not breakable: species carry no breakable data.
    const log = getEnvSpecies('env.deadwood.log')!;
    const logHull = envVariant(log, 0).shapes;
    expect([logHull.length, logHull[0]!.kind, logHull[0]!.blocks, log.nav, log.role, log.category, log.surface, propMaterial('env.deadwood.log'), propMaterial('prop.log')]).toEqual([1, 'hull', 'all', 'obstacle', 'cover', 'deadwood', 'bark', 'heavy_wood', 'heavy_wood']);
    log.variants[0]!.size.forEach((v, k) => expect(Math.abs(v - getProp('prop.log')!.size[k]!), `log axis ${k}`).toBeLessThan(0.08));
    expect(getProp('env.deadwood.log')!.breakable).toBeUndefined();
    expect(envTilts('env.deadwood.log')).toBe(false);
  });

  it('every shape lies inside the species\' visual bounds', () => {
    for (const s of ENV_SPECIES)
      for (const v of s.variants) {
        const [w, h, d] = v.size;
        for (const sh of v.shapes)
          for (const [x, y, z] of shapePoints(sh)) {
            // A little slack for the trunk capsule's rounded end below ground and the hull's worn edges.
            expect(Math.abs(x) <= w / 2 + 0.05 && Math.abs(z) <= d / 2 + 0.05 && y <= h + 0.05 && y >= -1.6, `${s.id} ${sh.kind} (${x}, ${y}, ${z})`).toBe(true);
          }
      }
  });

  it('a species reads as a prop: no collision box (its shapes collide), its first variant\'s file and size', () => {
    const oak = getProp('env.broadleaf.oak')!;
    expect(oak).toBe(envPropDefinition('env.broadleaf.oak'));
    expect(oak.collision).toBeNull();
    expect(oak.file).toBe('env/broadleaf.oak.summer.glb');
    expect(envModelFile('env.broadleaf.oak', 1)).toBe('env/broadleaf.oak.autumn.glb');
    // An unknown variant falls back to the first.
    expect(envModelFile('env.broadleaf.oak', 9)).toBe('env/broadleaf.oak.summer.glb');
    expect(getProp('env.shrub.broadleaf')!.conceals).toBe(true);
    expect(getProp('env.nothing.here')).toBeUndefined();
  });

  it('the resolution is pinned: shapes and sizes only change with an assetVersion bump (fixtures/environment-resolved.json)', () => {
    for (const s of ENV_SPECIES) {
      const key = `${s.id}@${s.assetVersion}`;
      expect(fixture[key], `${key}: not in the fixture (bumped assetVersion? add its entry on purpose)`).toBeDefined();
      expect(resolved(s.id), `${key}: a shape or size changed without an assetVersion bump`).toEqual(fixture[key]);
    }
  });
});

describe('environment budget (docs/MAP_BUDGETS.md)', () => {
  const prop = (i: number, model: string, variant?: number) => ({ id: `p${i}`, kind: 'prop', model, position: [i % 60, 0, Math.floor(i / 60)], yaw: 0, scale: 1, solid: true, tint: null, ...(variant !== undefined ? { variant } : {}) });
  const codes = (entities: unknown[]) => validateMap({ ...newMapDocument('Budget'), entities } as MapDocument).filter((i) => i.code.startsWith('budget.')).map((i) => i.code);

  it('env species count apart from props: 2,000 trees stay within the environment budget and leave the props budget alone', () => {
    expect(codes(Array.from({ length: 2000 }, (_, i) => prop(i, 'env.broadleaf.oak', i % 2)))).toEqual([]);
    expect(codes(Array.from({ length: MAP_BUDGETS.props + 1 }, (_, i) => prop(i, 'prop.crate')))).toContain('budget.props');
  });

  it('warns over the environment budgets: placements, colliding species, cliffs', () => {
    expect(codes(Array.from({ length: MAP_BUDGETS.env.placements + 1 }, (_, i) => prop(i, 'env.grass.clump')))).toEqual(['budget.env']);
    expect(codes(Array.from({ length: MAP_BUDGETS.env.colliding + 1 }, (_, i) => prop(i, 'env.rock.boulder_angular')))).toEqual(['budget.env_colliding']);
    expect(codes(Array.from({ length: MAP_BUDGETS.env.cliffs + 1 }, (_, i) => prop(i, 'env.cliff.face')))).toEqual(['budget.env_cliffs']);
  });

  it('the environment showcase (2,526 species placed) validates clean', () => {
    const loaded = loadMap(readFileSync(new URL('../../../maps/env_showcase.json', import.meta.url), 'utf8'));
    expect(loaded.ok).toBe(true);
    expect(loaded.issues.map((i) => `${i.code}: ${i.message}`)).toEqual([]);
  });
});
